export const calcWf = (w:number, sh:number) => { const r = +(w * (w > 180 ? 1.07 : 1.1)).toFixed(2), tax = +(r * 0.0825).toFixed(2), tot = +((r + sh + tax + 0.3) / 0.971).toFixed(2); return { r, sh, tax, tot }; };
